"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["80665"],{74046(e,t,a){a.r(t),a.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>s,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"tangfen/basiclabortheoryofvalue","title":"","description":"Marx was not born a labor theory of value advocate. The young Marx even opposed the labor theory of value for a time. The reason Marx ultimately accepted the labor theory of value and gave it a comprehensive overhaul was the final establishment of historical materialism. Without the establishment of historical materialism, there would be no Marxian labor theory of value, much less the discovery of surplus value. This historical and logical relationship must first be made clear.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/basiclabortheoryofvalue.md","sourceDirName":"tangfen","slug":"/tangfen/basiclabortheoryofvalue","permalink":"/en/tangfen/basiclabortheoryofvalue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"basiclabortheoryofvalue","title":"","hide_table_of_contents":true,"sidebar_label":"A summary explanation of Marx\'s value categories and labor theory of value"},"sidebar":"tangfenSidebar","previous":{"title":"[French Chef], your example about all finite natural numbers is not the same thing as Ms. Chan\'s","permalink":"/en/tangfen/toflxdcsf5"},"next":{"title":"Not speaking for anyone this time \u2014 discussing what value is with Yunguzhi!","permalink":"/en/tangfen/whatisvalue"}}'),i=a(74848),n=a(28453);let r={id:"basiclabortheoryofvalue",title:"",hide_table_of_contents:!0,sidebar_label:"A summary explanation of Marx's value categories and labor theory of value"},s="A General Explanation of Marx's Value Category and the Labor Theory of Value",l={},h=[];function c(e){let t={h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"a-general-explanation-of-marxs-value-category-and-the-labor-theory-of-value",children:"A General Explanation of Marx's Value Category and the Labor Theory of Value"})}),"\n",(0,i.jsx)(t.p,{children:"Marx was not born a labor theory of value advocate. The young Marx even opposed the labor theory of value for a time. The reason Marx ultimately accepted the labor theory of value and gave it a comprehensive overhaul was the final establishment of historical materialism. Without the establishment of historical materialism, there would be no Marxian labor theory of value, much less the discovery of surplus value. This historical and logical relationship must first be made clear."}),"\n",(0,i.jsx)(t.p,{children:"Value is a historical category. Its essence is the totality of relations between people in the social structure. Any category can be examined from both qualitative and quantitative aspects. On the qualitative side, it is the intrinsic determinacy of relations between people in the social structure. On the quantitative side, it manifests in exchange as the exchange ratio between exchanged objects. The quantitative aspect of value is also called exchange value."}),"\n",(0,i.jsx)(t.p,{children:"On the qualitative side of value, since it is the intrinsic determinacy of relations between people in the social structure, it reflects the relations between people in the social structure. The general relations between people correspond to abstract labor in the general human sense, while the particular relations between people (that is, activities between specific individuals, etc.) correspond to concrete labor in the particular sense. Abstract labor determines the general determinacy on the qualitative side of value, while concrete labor determines the particular determinacy on the qualitative side of value, which is use value."}),"\n",(0,i.jsx)(t.p,{children:'Price is the monetization of value. Some may ask: wasn\'t there price before currency existed? In fact, currency is also a historical category. The historical process of value taking the price form is the historical process of monetization. There is no issue of "no price before currency existed." The so-called relationship of supply and demand is merely one of the relationships between people, and it cannot even determine price, let alone value, whose essence is the totality of relations between people in the social structure.'}),"\n",(0,i.jsx)(t.p,{children:"Marx's value structure is very clear. It examines the value category from the standpoint of social totality, not from isolated phenomena or certain a priori premises as ordinary people do. Without standing on the standpoint of social totality and historical categories, it is impossible to truly understand Marx's labor theory of value -- note, not the labor theory of value in general, but Marx's specifically. All attempts to negate Marx's labor theory of value result from taking some single relationship between people, magnifying it into the sole a priori relationship. As long as you grasp this key point, everything becomes readily solvable."})]})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,a){a.d(t,{R:()=>r,x:()=>s});var o=a(96540);let i={},n=o.createContext(i);function r(e){let t=o.useContext(n);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(n.Provider,{value:t},e.children)}}}]);